<?php require_once __DIR__.'/../inc/functions.php';require_login();$errors=[];$v=['name'=>'','email'=>'','phone'=>'','address'=>''];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach($v as $k=>$x)$v[$k]=trim($_POST[$k]??'');if($v['name']===''||mb_strlen($v['name'])>100)$errors[]='الاسم مطلوب ويجب ألا يتجاوز 100 محرف.';if(!valid_email($v['email'])||mb_strlen($v['email'])>100)$errors[]='البريد الإلكتروني غير صحيح.';if($v['phone']===''||mb_strlen($v['phone'])>15)$errors[]='الهاتف مطلوب وبحد أقصى 15 محرفاً.';if($v['address']==='')$errors[]='العنوان مطلوب.';if(!$errors){try{$pic=upload_picture($_FILES['profile_picture']??[]);$q=db()->prepare('INSERT INTO students(name,email,phone,address,profile_picture) VALUES(?,?,?,?,?)');$q->execute([$v['name'],$v['email'],$v['phone'],$v['address'],$pic]);flash('success','تمت إضافة الطالب بنجاح.');redirect('/students/index.php');}catch(Throwable $ex){if(isset($pic))delete_picture($pic);$errors[]=$ex instanceof PDOException&&$ex->getCode()==='23000'?'البريد الإلكتروني مسجل لطالب آخر.':$ex->getMessage();}}}$title='إضافة طالب';require __DIR__.'/../inc/header.php';require __DIR__.'/form.php';require __DIR__.'/../inc/footer.php';